DROP TABLE IF EXISTS `agent_run`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `agent_run` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT '运行ID',
  `tenant_id` bigint(20) NOT NULL COMMENT '租户ID',
  `trace_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '链路追踪ID(每轮请求唯一)',
  `conversation_uuid` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '会话UUID',
  `run_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'CHAT' COMMENT '运行类型',
  `intent` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '本轮意图',
  `model_provider` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '模型提供商',
  `model_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '模型名',
  `router_decision` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '路由决策',
  `input_redacted` varchar(2048) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '脱敏后的用户输入',
  `input_hash` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '用户输入 SHA-256(用于去重/比对)',
  `final_answer_redacted` text COLLATE utf8mb4_unicode_ci COMMENT '脱敏后的最终回答',
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'RUNNING' COMMENT 'RUNNING/SUCCESS/FAILED',
  `failure_category` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '失败分类',
  `failure_reason` varchar(1024) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '失败原因(已脱敏、截断)',
  `prompt_tokens` bigint(20) NOT NULL DEFAULT '0' COMMENT '输入 token(当前未采集,恒为0)',
  `completion_tokens` bigint(20) NOT NULL DEFAULT '0' COMMENT '输出 token(当前未采集,恒为0)',
  `cost_usd` decimal(12,6) NOT NULL DEFAULT '0.000000' COMMENT '成本(当前未采集,恒为0)',
  `first_token_latency_ms` int(11) DEFAULT NULL COMMENT '首字延迟 ms(真实测量)',
  `total_latency_ms` int(11) DEFAULT NULL COMMENT '总耗时 ms(真实测量)',
  `tool_call_count` int(11) NOT NULL DEFAULT '0' COMMENT '工具调用数(来自 tool_call_log 真实统计)',
  `retrieved_doc_count` int(11) NOT NULL DEFAULT '0' COMMENT '检索文档数(当前未采集,恒为0)',
  `citation_count` int(11) NOT NULL DEFAULT '0' COMMENT '引用数(当前未采集,恒为0)',
  `started_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '开始时间',
  `finished_at` datetime(3) DEFAULT NULL COMMENT '结束时间',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_trace_id` (`trace_id`),
  KEY `idx_tenant_started` (`tenant_id`,`started_at`),
  KEY `idx_tenant_status` (`tenant_id`,`status`,`started_at`),
  KEY `idx_conversation` (`tenant_id`,`conversation_uuid`)
) ENGINE=InnoDB AUTO_INCREMENT=65 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Agent 执行轨迹(每次调用一条)';
/*!40101 SET character_set_client = @saved_cs_client */;

