DROP TABLE IF EXISTS `agent_state_transition`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `agent_state_transition` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `tenant_id` bigint(20) unsigned NOT NULL COMMENT '租户ID',
  `conversation_uuid` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '会话UUID',
  `trace_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '触发本次转换的 traceId',
  `from_state` varchar(48) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '转换前状态',
  `to_state` varchar(48) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '转换后状态',
  `trigger_type` varchar(48) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '触发类型:SUPERVISOR/ROUTER/TOOL/RESPONSE/FAILURE',
  `trigger_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '触发名称:specialist 或 toolName',
  `reason_redacted` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '转换原因(已脱敏)',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  KEY `idx_agent_transition_conversation` (`tenant_id`,`conversation_uuid`,`created_at`),
  KEY `idx_agent_transition_trace` (`tenant_id`,`trace_id`)
) ENGINE=InnoDB AUTO_INCREMENT=171 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='会话状态转换历史(只追加,可回放)';
/*!40101 SET character_set_client = @saved_cs_client */;

