--
-- Table structure for table `agent_step`
--

DROP TABLE IF EXISTS `agent_step`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `agent_step` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT '步骤ID',
  `tenant_id` bigint(20) NOT NULL COMMENT '租户ID',
  `agent_run_id` bigint(20) unsigned NOT NULL COMMENT '关联 agent_run.id',
  `trace_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '链路追踪ID(关联 agent_run.trace_id)',
  `step_index` int(11) NOT NULL COMMENT '同一 Run 内步骤序号(从1开始)',
  `step_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'ROUTER/MEMORY/TOOL/FINAL_ANSWER/FAILURE',
  `name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '步骤名称',
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'SUCCESS' COMMENT 'SUCCESS/FAILED',
  `input_summary` varchar(2048) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '输入摘要(已脱敏)',
  `output_summary` varchar(2048) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '输出摘要(已脱敏)',
  `tool_call_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工具调用ID(TOOL 步骤)',
  `latency_ms` int(11) DEFAULT NULL COMMENT '耗时 ms',
  `failure_category` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '失败分类',
  `failure_reason` varchar(1024) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '失败原因(已脱敏)',
  `metadata_json` text COLLATE utf8mb4_unicode_ci COMMENT '扩展元数据 JSON',
  `started_at` datetime(3) DEFAULT NULL,
  `ended_at` datetime(3) DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  KEY `idx_trace_step` (`trace_id`,`step_index`),
  KEY `idx_run_step` (`agent_run_id`,`step_index`),
  KEY `idx_tool_call` (`tool_call_id`),
  KEY `idx_tenant_type` (`tenant_id`,`step_type`,`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=285 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Agent 轨迹步骤(一次 Run 多条)';
/*!40101 SET character_set_client = @saved_cs_client */;

