DROP TABLE IF EXISTS `chat_message`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `chat_message` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT '消息ID',
  `message_uuid` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '消息UUID',
  `conversation_uuid` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '会话UUID(冗余便于跨表查询)',
  `conversation_id` bigint(20) unsigned NOT NULL COMMENT '会话ID',
  `tenant_id` bigint(20) unsigned NOT NULL COMMENT '租户ID',
  `role` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '角色:user/assistant/system/tool',
  `seq_no` int(11) NOT NULL COMMENT '会话内消息序号(从1开始)',
  `content` mediumtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '消息内容(原文,可能含富文本/markdown)',
  `content_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'TEXT' COMMENT '内容类型:TEXT/IMAGE/FILE/VOICE/MARKDOWN/HTML',
  `attachments` json DEFAULT NULL COMMENT '附件列表 [{"type":"image","url":"...","size":1024}]',
  `original_lang` varchar(8) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '原始语言',
  `detection_confidence` decimal(6,5) DEFAULT NULL,
  `translated_content` mediumtext COLLATE utf8mb4_unicode_ci COMMENT '翻译为英语后的内容(用于 LLM 处理)',
  `translation_lang` varchar(8) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '翻译目标语言',
  `is_translated` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否翻译过',
  `translation_provider` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `translation_model` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `translation_status` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `translation_latency_ms` int(11) DEFAULT NULL,
  `translation_fallback_reason` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tool_calls` json DEFAULT NULL COMMENT '工具调用列表 [{"id":"xxx","name":"queryOrder","args":{...}}]',
  `tool_call_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '本消息是哪次工具调用的结果(role=tool 时)',
  `tool_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工具名(role=tool 时)',
  `model_provider` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'LLM 提供商:openai/anthropic/deepseek',
  `model_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '具体模型名:gpt-4o-mini/claude-haiku-4-5',
  `prompt_tokens` int(11) NOT NULL DEFAULT '0' COMMENT '输入 token 数',
  `completion_tokens` int(11) NOT NULL DEFAULT '0' COMMENT '输出 token 数',
  `total_tokens` int(11) NOT NULL DEFAULT '0' COMMENT '总 token 数',
  `cost_usd` decimal(12,8) NOT NULL DEFAULT '0.00000000' COMMENT '本条消息成本 USD(精度高,单条可能很小)',
  `latency_ms` int(11) DEFAULT NULL COMMENT '生成耗时 ms',
  `ttfb_ms` int(11) DEFAULT NULL COMMENT '首字延迟 ms(流式)',
  `finish_reason` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '终止原因:stop/length/tool_calls/content_filter',
  `confidence` decimal(4,3) DEFAULT NULL COMMENT '置信度[0,1](意图分类/工具选择)',
  `is_filtered` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否被过滤(敏感内容):0否1是',
  `filter_reason` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '过滤原因:PII/INJECTION/TOXIC/SPAM',
  `is_streamed` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否流式输出',
  `iteration_index` tinyint(4) DEFAULT NULL COMMENT 'ReAct 第几轮迭代(1-5)',
  `parent_message_id` bigint(20) unsigned DEFAULT NULL COMMENT '父消息ID(工具结果指向触发它的 assistant 消息)',
  `ext_attr` json DEFAULT NULL COMMENT '扩展属性',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_message_uuid` (`message_uuid`) COMMENT '消息UUID唯一',
  UNIQUE KEY `uk_conv_seq` (`conversation_id`,`seq_no`) COMMENT '会话内序号唯一',
  KEY `idx_conversation` (`conversation_uuid`,`created_at`) COMMENT '加载会话历史(最常用)',
  KEY `idx_tenant_created` (`tenant_id`,`created_at`) COMMENT '租户消息流',
  KEY `idx_tenant_role` (`tenant_id`,`role`,`created_at`) COMMENT '统计 role 分布',
  KEY `idx_tool_call` (`tool_call_id`) COMMENT '工具调用追踪',
  KEY `idx_model` (`model_name`,`created_at`) COMMENT '模型用量统计',
  KEY `idx_filtered` (`is_filtered`,`created_at`) COMMENT '安全审计'
) ENGINE=InnoDB AUTO_INCREMENT=727 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='消息表';
/*!40101 SET character_set_client = @saved_cs_client */;

