INSERT INTO `chat_message` VALUES (351,'msg-5001-1','conv-f1001-0001',5001,1001,'user',1,'Hi, my order #1001 still shows as shipped. When will it arrive?','TEXT',NULL,'en',NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0.00000000,NULL,NULL,NULL,NULL,0,NULL,0,NULL,NULL,NULL,'2026-09-26 10:00:10.000'),(352,'msg-5001-2','conv-f1001-0001',5001,1001,'assistant',2,'Hello Ava! Let me check order #1001 for you. It is currently in transit with the carrier and the latest tracking shows it has left the origin facility. Estimated delivery is within 3-5 business days.','TEXT',NULL,'en',NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'queryOrder','openai','gpt-4o-mini',410,150,560,0.00031000,950,NULL,'stop',0.960,0,NULL,1,1,NULL,NULL,'2026-09-26 10:01:00.000'),(353,'msg-5001-3','conv-f1001-0001',5001,1001,'user',3,'Great, could you also send me the tracking number?','TEXT',NULL,'en',NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0.00000000,NULL,NULL,NULL,NULL,0,NULL,0,NULL,NULL,NULL,'2026-09-26 10:03:00.000'),(354,'msg-5001-4','conv-f1001-0001',5001,1001,'assistant',4,'Of course. The tracking number for #1001 is NS1001US. You can use it on the carrier website for live updates. Is there anything else I can help you with?','TEXT',NULL,'en',NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'queryOrder','openai','gpt-4o-mini',410,160,570,0.00033000,1150,NULL,'stop',0.950,0,NULL,1,1,NULL,NULL,'2026-09-26 10:04:30.000'),(355,'msg-5002-1','conv-f1001-0002',5002,1001,'user',1,'Hola, quiero confirmar si mi pedido #1002 ya fue entregado.','TEXT',NULL,'es',NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0.00000000,NULL,NULL,NULL,NULL,0,NULL,0,NULL,NULL,NULL,'2026-09-26 11:30:10.000'),(356,'msg-5002-2','conv-f1001-0002',5002,1001,'assistant',2,'Hola Lucia! Reviso el pedido #1002. El estado es \"entregado\" y fue firmado en tu direccion. La entrega se completo correctamente.','TEXT',NULL,'es',NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'queryOrder','openai','gpt-4o-mini',390,140,530,0.00030000,1100,NULL,'stop',0.970,0,NULL,1,1,NULL,NULL,'2026-09-26 11:31:00.000'),(357,'msg-5002-3','conv-f1001-0002',5002,1001,'user',3,'Perfecto, muchas gracias. El paquete llego en buen estado.','TEXT',NULL,'es',NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0.00000000,NULL,NULL,NULL,NULL,0,NULL,0,NULL,NULL,NULL,'2026-09-26 11:33:00.000'),(358,'msg-5002-4','conv-f1001-0002',5002,1001,'assistant',4,'Me alegra saberlo! Si necesitas algo mas, aqui estamos. Gracias por tu compra.','TEXT',NULL,'es',NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'openai','gpt-4o-mini',370,100,470,0.00022000,1300,NULL,'stop',0.980,0,NULL,1,1,NULL,NULL,'2026-09-26 11:34:30.000'),(359,'msg-5003-1','conv-f1001-0003',5003,1001,'user',1,'Hello, do you have the noise-cancelling earbuds in stock? I am thinking about buying them.','TEXT',NULL,'en',NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0.00000000,NULL,NULL,NULL,NULL,0,NULL,0,NULL,NULL,NULL,'2026-09-26 14:20:10.000'),(360,'msg-5003-2','conv-f1001-0003',5003,1001,'assistant',2,'Hi Noah! Yes, the Active Noise-Cancelling Earbuds Pro (VL-EARBUD-PRO) are in stock. They are priced at 129 USD and currently available for immediate shipping.','TEXT',NULL,'en',NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'searchProductCatalog','openai','gpt-4o-mini',360,130,490,0.00027000,850,NULL,'stop',0.940,0,NULL,1,1,NULL,NULL,'2026-09-26 14:21:00.000'),(361,'msg-5003-3','conv-f1001-0003',5003,1001,'user',3,'Nice. What is the battery life like?','TEXT',NULL,'en',NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0.00000000,NULL,NULL,NULL,NULL,0,NULL,0,NULL,NULL,NULL,'2026-09-26 14:23:00.000'),(362,'msg-5003-4','conv-f1001-0003',5003,1001,'assistant',4,'The earbuds offer up to 30 hours of total playtime with the charging case, and about 8 hours on a single charge. They also support fast charging.','TEXT',NULL,'en',NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'searchProductCatalog','openai','gpt-4o-mini',340,130,470,0.00023000,1050,NULL,'stop',0.930,0,NULL,1,1,NULL,NULL,'2026-09-26 14:24:30.000'),(363,'msg-5004-1','conv-f1001-0004',5004,1001,'user',1,'Bonjour, ou en est le remboursement de ma commande #1004 ?','TEXT',NULL,'fr',NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0.00000000,NULL,NULL,NULL,NULL,0,NULL,0,NULL,NULL,NULL,'2026-09-25 09:10:10.000'),(364,'msg-5004-2','conv-f1001-0004',5004,1001,'assistant',2,'Bonjour Emma! La commande #1004 est marquee comme remboursee. Le remboursement a ete traite et devrait apparaitre sur votre moyen de paiement initial sous 3 a 5 jours ouvrables.','TEXT',NULL,'fr',NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'queryOrder','openai','gpt-4o-mini',420,160,580,0.00032000,1200,NULL,'stop',0.950,0,NULL,1,1,NULL,NULL,'2026-09-25 09:11:00.000'),(365,'msg-5004-3','conv-f1001-0004',5004,1001,'user',3,'D accord, mais je ne vois encore rien sur mon compte.','TEXT',NULL,'fr',NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0.00000000,NULL,NULL,NULL,NULL,0,NULL,0,NULL,NULL,NULL,'2026-09-25 09:13:00.000'),(366,'msg-5004-4','conv-f1001-0004',5004,1001,'assistant',4,'Je comprends votre inquietude. Le delai bancaire peut prendre quelques jours supplementaires selon votre banque. Si vous ne voyez rien apres 5 jours ouvrables, revenez vers nous et nous ouvrirons une verification aupres du processeur de paiement.','TEXT',NULL,'fr',NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'queryOrder','openai','gpt-4o-mini',460,180,640,0.00038000,1450,NULL,'stop',0.920,0,NULL,1,1,NULL,NULL,'2026-09-25 09:14:30.000'),(367,'msg-5005-1','conv-f1001-0005',5005,1001,'user',1,'Why was my order #1005 cancelled? I want it shipped right now!','TEXT',NULL,'en',NULL,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0.00000000,NULL,NULL,NULL,NULL,0,NULL,0,NULL,NULL,NULL,'