CREATE TABLE `commerce_action_policy` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint(20) unsigned NOT NULL,
  `action_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'RETURN/REFUND/REPLACEMENT/ADDRESS_CHANGE/CANCEL_ORDER/COUPON',
  `approval_required` tinyint(1) NOT NULL DEFAULT '1',
  `min_approver_role` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'SUPPORT_SUPERVISOR',
  `amount_threshold` decimal(15,4) DEFAULT NULL,
  `requires_identity_verification` tinyint(1) NOT NULL DEFAULT '1',
  `idempotency_window_minutes` int(11) NOT NULL DEFAULT '60',
  `external_write_enabled` tinyint(1) NOT NULL DEFAULT '0',
  `policy_note` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_action_policy` (`tenant_id`,`action_type`),
  KEY `idx_action_policy_active` (`tenant_id`,`active`)
) ENGINE=InnoDB AUTO_INCREMENT=49 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Approval gate policy for high-risk commerce actions';
