--
-- Table structure for table `conversation`
--

DROP TABLE IF EXISTS `conversation`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `conversation` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT '会话ID',
  `conversation_uuid` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '会话UUID(对外暴露,不暴露自增ID)',
  `tenant_id` bigint(20) unsigned NOT NULL COMMENT '租户ID',
  `customer_id` bigint(20) unsigned DEFAULT NULL COMMENT '客户ID(关联 customer.id,首次咨询可能为空)',
  `external_customer_id` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '平台客户ID',
  `customer_email` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户邮箱(用于身份验证)',
  `customer_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户名(快照)',
  `related_order_id` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关联的平台订单号(可空)',
  `related_product_ids` json DEFAULT NULL COMMENT '咨询涉及的商品ID列表',
  `channel` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'WEB' COMMENT '渠道:WEB/EMAIL/WHATSAPP/MESSENGER/PLATFORM_IM',
  `language` varchar(8) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '会话主语言(首条消息检测)',
  `intent_primary` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '主意图:ORDER_QUERY/LOGISTICS/REFUND/PRODUCT/COMPLAINT/GREETING/UNCLEAR',
  `intent_history` json DEFAULT NULL COMMENT '历史意图变化轨迹',
  `sentiment` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '情感倾向:POSITIVE/NEUTRAL/NEGATIVE/ANGRY',
  `sentiment_score` decimal(4,3) DEFAULT NULL COMMENT '情感分[-1,1]',
  `status` tinyint(4) NOT NULL DEFAULT '1' COMMENT '1:进行中(AI) 2:已完成 3:已升级人工 4:人工处理中 5:已关闭 6:已超时',
  `escalated` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否升级人工:0否1是',
  `escalation_reason` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '升级原因:LOW_CONFIDENCE/AMOUNT_LIMIT/NEGATIVE_SENTIMENT/MAX_ITER/USER_REQUEST/AI_PROACTIVE',
  `escalated_at` datetime(3) DEFAULT NULL COMMENT '升级时间',
  `human_agent_id` bigint(20) unsigned DEFAULT NULL COMMENT '接管的人工客服ID',
  `priority` tinyint(4) NOT NULL DEFAULT '2' COMMENT '优先级:1低 2中 3高 4紧急',
  `message_count` int(11) NOT NULL DEFAULT '0' COMMENT '消息总数(user+assistant)',
  `tool_call_count` int(11) NOT NULL DEFAULT '0' COMMENT '工具调用总数',
  `total_prompt_tokens` bigint(20) NOT NULL DEFAULT '0' COMMENT '会话累计 prompt token',
  `total_completion_tokens` bigint(20) NOT NULL DEFAULT '0' COMMENT '会话累计 completion token',
  `total_cost_usd` decimal(12,6) NOT NULL DEFAULT '0.000000' COMMENT '会话总成本 USD',
  `first_response_ms` int(11) DEFAULT NULL COMMENT '首字响应时间 ms',
  `avg_response_ms` int(11) DEFAULT NULL COMMENT '平均响应时间 ms',
  `csat_score` tinyint(4) DEFAULT NULL COMMENT '客户满意度[1,5]',
  `csat_comment` varchar(1024) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户评论',
  `csat_submitted_at` datetime DEFAULT NULL COMMENT '评分提交时间',
  `resolved` tinyint(1) DEFAULT NULL COMMENT '问题是否解决:NULL未知 0否 1是',
  `started_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '会话开始时间',
  `last_message_at` datetime(3) DEFAULT NULL COMMENT '最后消息时间',
  `ended_at` datetime(3) DEFAULT NULL COMMENT '会话结束时间',
  `duration_seconds` int(11) DEFAULT NULL COMMENT '会话时长秒(ended-started)',
  `ext_attr` json DEFAULT NULL COMMENT '扩展属性',
  `tags` json DEFAULT NULL COMMENT '标签 ["urgent","vip","followup"]',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  `version` int(11) NOT NULL DEFAULT '0' COMMENT '乐观锁',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_conversation_uuid` (`conversation_uuid`) COMMENT 'UUID 唯一',
  KEY `idx_tenant_customer` (`tenant_id`,`customer_id`,`started_at`) COMMENT '客户的会话列表',
  KEY `idx_tenant_status` (`tenant_id`,`status`,`started_at`) COMMENT '按状态筛选',
  KEY `idx_tenant_started` (`tenant_id`,`started_at`) COMMENT '时间倒序列表',
  KEY `idx_tenant_escalated` (`tenant_id`,`escalated`,`escalated_at`) COMMENT '人工工单查询',
  KEY `idx_tenant_intent` (`tenant_id`,`intent_primary`) COMMENT '按意图统计',
  KEY `idx_human_agent` (`human_agent_id`,`status`) COMMENT '客服我的工单',
  KEY `idx_related_order` (`tenant_id`,`related_order_id`) COMMENT '订单关联会话查询',
  KEY `idx_last_message` (`last_message_at`) COMMENT '超时会话扫描'
) ENGINE=InnoDB AUTO_INCREMENT=5628 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='会话表';
/*!40101 SET character_set_client = @saved_cs_client */;

