--
-- Table structure for table `customer`
--

DROP TABLE IF EXISTS `customer`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `customer` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT '客户ID',
  `tenant_id` bigint(20) unsigned NOT NULL COMMENT '租户ID',
  `external_customer_id` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '平台客户ID',
  `email` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '邮箱(主联系方式)',
  `phone` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '手机(含国家码)',
  `first_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '名',
  `last_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '姓',
  `display_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '显示名(优先用)',
  `avatar_url` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '头像 URL',
  `country_code` varchar(8) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户所在国 ISO-3166',
  `state_province` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '州/省',
  `city` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '城市',
  `language_pref` varchar(8) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户偏好语言(基于历史对话推断)',
  `timezone` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户时区',
  `currency_pref` varchar(8) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户偏好币种',
  `total_orders` int(11) NOT NULL DEFAULT '0' COMMENT '历史订单总数',
  `total_spent` decimal(15,4) NOT NULL DEFAULT '0.0000' COMMENT '累计消费金额(以 tenant.currency 计)',
  `avg_order_value` decimal(15,4) NOT NULL DEFAULT '0.0000' COMMENT '平均客单价',
  `last_order_at` datetime DEFAULT NULL COMMENT '最后下单时间',
  `customer_tier` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户等级:NEW/REGULAR/VIP/CHURN',
  `total_conversations` int(11) NOT NULL DEFAULT '0' COMMENT '累计会话数',
  `total_complaints` int(11) NOT NULL DEFAULT '0' COMMENT '累计投诉次数',
  `satisfaction_avg` decimal(3,2) DEFAULT NULL COMMENT '平均满意度[1,5]',
  `last_contact_at` datetime DEFAULT NULL COMMENT '最后联系时间',
  `is_blacklisted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否拉黑(恶意/欺诈):0否1是',
  `blacklist_reason` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '拉黑原因',
  `synced_at` datetime DEFAULT NULL COMMENT '从平台最后同步时间',
  `sync_status` tinyint(4) NOT NULL DEFAULT '0' COMMENT '同步状态:0未同步 1成功 2失败',
  `sync_error` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '同步失败原因',
  `ext_attr` json DEFAULT NULL COMMENT '扩展属性(平台原始 customer 数据缓存)',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  `version` int(11) NOT NULL DEFAULT '0' COMMENT '乐观锁',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_tenant_external` (`tenant_id`,`external_customer_id`) COMMENT '租户内平台客户ID唯一',
  KEY `idx_tenant_email` (`tenant_id`,`email`) COMMENT '邮箱查询',
  KEY `idx_tenant_phone` (`tenant_id`,`phone`) COMMENT '手机查询',
  KEY `idx_tenant_tier` (`tenant_id`,`customer_tier`) COMMENT '按等级筛选',
  KEY `idx_tenant_blacklist` (`tenant_id`,`is_blacklisted`) COMMENT '黑名单过滤',
  KEY `idx_tenant_last_order` (`tenant_id`,`last_order_at`) COMMENT '客户活跃度排序',
  KEY `idx_synced_at` (`synced_at`) COMMENT '同步任务调度'
) ENGINE=InnoDB AUTO_INCREMENT=2017 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='终端客户表';
/*!40101 SET character_set_client = @saved_cs_client */;

