--
-- Table structure for table `escalation_record`
--

DROP TABLE IF EXISTS `escalation_record`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `escalation_record` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT '工单ID',
  `ticket_no` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '工单编号(对外展示)',
  `tenant_id` bigint(20) unsigned NOT NULL COMMENT '租户ID',
  `conversation_uuid` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '会话UUID',
  `customer_id` bigint(20) unsigned DEFAULT NULL COMMENT '客户ID',
  `escalation_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'AUTO_AI/AI_PROACTIVE/USER_REQUEST',
  `escalation_reason` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'LOW_CONFIDENCE/AMOUNT_LIMIT/NEGATIVE_SENTIMENT/MAX_ITER/TOOL_FAILURE/USER_REQUEST',
  `reason_detail` varchar(1024) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '详细原因',
  `confidence_score` decimal(4,3) DEFAULT NULL COMMENT '触发时的置信度',
  `sentiment_score` decimal(4,3) DEFAULT NULL COMMENT '触发时的情感分',
  `involved_amount` decimal(15,4) DEFAULT NULL COMMENT '涉及金额',
  `currency` varchar(8) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `summary` text COLLATE utf8mb4_unicode_ci COMMENT 'AI 生成的会话摘要(给人工看)',
  `customer_intent` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户主诉意图',
  `priority` tinyint(4) NOT NULL DEFAULT '2' COMMENT '1低 2中 3高 4紧急',
  `assigned_agent_id` bigint(20) unsigned DEFAULT NULL COMMENT '分配的客服ID',
  `assigned_at` datetime(3) DEFAULT NULL COMMENT '分配时间',
  `assignment_strategy` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'AUTO_LEAST_BUSY/MANUAL/SKILL_MATCH',
  `sla_response_seconds` int(11) NOT NULL DEFAULT '300' COMMENT 'SLA 响应时长',
  `sla_resolve_seconds` int(11) NOT NULL DEFAULT '3600' COMMENT 'SLA 解决时长',
  `sla_response_due_at` datetime DEFAULT NULL COMMENT 'SLA 响应截止时间',
  `sla_resolve_due_at` datetime DEFAULT NULL COMMENT 'SLA 解决截止时间',
  `sla_response_breached` tinyint(1) NOT NULL DEFAULT '0' COMMENT '响应是否违约',
  `sla_resolve_breached` tinyint(1) NOT NULL DEFAULT '0' COMMENT '解决是否违约',
  `status` tinyint(4) NOT NULL DEFAULT '1' COMMENT '1待分配 2待响应 3处理中 4已解决 5已关闭 6已取消',
  `first_response_at` datetime(3) DEFAULT NULL COMMENT '首次响应时间',
  `resolved_at` datetime(3) DEFAULT NULL COMMENT '解决时间',
  `closed_at` datetime(3) DEFAULT NULL COMMENT '关闭时间',
  `resolution` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '解决方式:RESOLVED/REFUNDED/REPLACED/EXPLAINED/UNRESOLVED',
  `resolution_note` text COLLATE utf8mb4_unicode_ci COMMENT '解决备注',
  `csat_score` tinyint(4) DEFAULT NULL COMMENT '客户满意度',
  `csat_comment` varchar(1024) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `parent_ticket_id` bigint(20) unsigned DEFAULT NULL COMMENT '父工单ID(二次升级)',
  `escalated_back_to_ai` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否再次交回 AI',
  `tags` json DEFAULT NULL,
  `ext_attr` json DEFAULT NULL,
  `version` int(11) NOT NULL DEFAULT '0',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ticket_no` (`ticket_no`),
  KEY `idx_tenant_status` (`tenant_id`,`status`,`priority`,`created_at`) COMMENT '工单池查询',
  KEY `idx_assigned` (`assigned_agent_id`,`status`) COMMENT '客服我的工单',
  KEY `idx_conversation` (`conversation_uuid`) COMMENT '会话工单关联',
  KEY `idx_sla_breach` (`tenant_id`,`sla_response_breached`,`sla_resolve_breached`) COMMENT 'SLA 监控',
  KEY `idx_priority_created` (`priority`,`created_at`) COMMENT '紧急工单优先'
) ENGINE=InnoDB AUTO_INCREMENT=6106 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='人工升级工单表';
/*!40101 SET character_set_client = @saved_cs_client */;

