INSERT INTO `escalation_record` VALUES (6001,'TKT-ESC-0001',1002,'conv-e1002-0004',2014,'USER_REQUEST','USER_REQUEST','客户明确要求人工处理承运商派送异常',0.420,-0.850,129.5600,'USD','订单 #2004 物流显示派送异常且已二次延误，客户要求人工介入联系承运商并给出明确处理方案。','LOGISTICS',4,NULL,NULL,NULL,300,3600,'2026-09-27 15:55:00','2026-09-27 16:45:00',0,0,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'[\"delivery_exception\", \"urgent\"]',NULL,0,'2026-09-27 15:50:00.000','2026-09-27 15:50:00.000'),(6002,'TKT-ESC-0002',1002,'conv-e1002-0003',2013,'AUTO_AI','LOW_CONFIDENCE','AI 无法确认订单 #2003 的具体发货时间，置信度不足',0.380,0.050,59.0000,'USD','客户询问订单 #2003 处理进度，需要人工确认发货时间。','ORDER_QUERY',3,1,'2026-09-27 12:10:00.000','MANUAL',300,3600,'2026-09-27 12:10:00','2026-09-27 13:00:00',0,0,3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'[\"order_progress\"]',NULL,0,'2026-09-27 12:05:00.000','2026-09-27 12:10:00.000'),(6003,'TKT-ESC-0003',1002,'conv-e1002-0005',2015,'USER_REQUEST','USER_REQUEST','客户要求人工协助办理退货与退款到账确认',0.550,-0.100,69.0000,'USD','客户咨询订单 #2005 退货流程及退款到账时间，人工介入处理。','REFUND',2,1,'2026-09-27 17:28:00.000','MANUAL',300,3600,'2026-09-27 17:28:00','2026-09-27 18:18:00',0,0,3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,'[\"refund\", \"vip\"]',NULL,0,'2026-09-27 17:26:00.000','2026-09-27 17:28:00.000'),(6004,'TKT-ESC-0004',1001,'conv-f1001-0004',2004,'AUTO_AI','AMOUNT_LIMIT','退款金额超过 AI 自动处理上限，需人工审核确认',0.910,-0.400,199.0000,'USD','客户就订单 #1004 退款到账时间提出疑问，已人工核实并确认退款处理完成。','REFUND',2,1,'2026-09-25 09:18:00.000','MANUAL',300,3600,'2026-09-25 09:18:00','2026-09-25 10:08:00',0,0,4,'2026-09-25 09:20:00.000','2026-09-25 09:40:00.000','2026-09-25 09:40:00.000','EXPLAINED','已确认退款已原路退回，向客户说明银行到账时间。',NULL,NULL,NULL,0,'[\"refund\", \"amount_limit\"]',NULL,0,'2026-09-25 09:16:00.000','2026-09-25 09:40:00.000'),(6005,'TKT-20261006203010-0319D6F3',1002,'conv-e1002-0005',2015,'AI_PROACTIVE','客户明确要求转人工客服','客户明确要求转人工客服',NULL,NULL,NULL,NULL,'客户主动发起请求，要求转接人工客服。客户暂未说明具体问题（如订单、物流或售后等），需要人工客服介入接待并进一步了解情况。','REFUND',2,NULL,NULL,NULL,300,3600,'2026-10-06 20:35:10','2026-10-06 21:30:10',0,0,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,0,'2026-10-06 20:30:10.124','2026-10-06 20:30:10.124'),(6006,'TKT-20261008110955-CFB6A9F2',1001,'11a943f9-7fbd-4a94-8fb8-64ef0a3fcbe9',NULL,'AI_PROACTIVE','客户明确要求转人工客服','客户明确要求转人工客服',NULL,NULL,NULL,NULL,'客户直接提出希望转接人工客服，未提供具体问题描述。当前无更多业务上下文，按客户要求升级至人工处理。','HUMAN_REQUEST',2,NULL,NULL,NULL,300,3600,'2026-10-08 11:14:55','2026-10-08 12:09:55',0,0,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,0,'2026-10-08 11:09:55.437','2026-10-08 11:09:55.437'),(6007,'TKT-20261008111032-E7B20431',1001,'bbea4c2c-50b4-4605-a9d8-e503643a72fa',NULL,'AI_PROACTIVE','客户明确要求转人工客服','客户明确要求转人工客服',NULL,NULL,NULL,NULL,'客户直接提出“我要转人工客服”，未提供具体问题描述，暂无其他已尝试的处理措施。','HUMAN_REQUEST',3,NULL,NULL,NULL,300,3600,'2026-10-08 11:15:32','2026-10-08 12:10:32',0,0,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,0,'2026-10-08 11:10:32.461','2026-10-08 11:10:32.461'),(6008,'TKT-20261008174015-CB147D15',1001,'02f197e1-60dc-48ea-bd89-16e6a6bd59e9',NULL,'AI_PROACTIVE','客户询问退款申请审批进度，当前无查询申请进度的工具，需人工核实并反馈','客户询问退款申请审批进度，当前无查询申请进度的工具，需人工核实并反馈',NULL,NULL,NULL,NULL,'订单 #1002（lucia@example.es），商品质量问题的退款申请已创建，状态为待人工审批。客户询问审批进度，AI 无查询进度工具，需人工核实申请 ACT-20261008174003-EAE2B492 的处理进展并回复客户。','RETURN_REFUND',2,NULL,NULL,NULL,300,3600,'2026-10-08 17:45:15','2026-10-08 18:40:15',0,0,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,0,'2026-10-08 17:40:15.298','2026-10-08 17:40:15.298'),(6009,'TKT-20261009230656-8B07597B',1001,'fd8cc339-7787-4730-b564-15af496fb6fc',NULL,'AI_PROACTIVE','客户明确要求转人工客服','客户明确要求转人工客服',NULL,NULL,NULL,NULL,'客户在会话中直接表示要转人工客服，未说明具体问题。当前已按客户要求升级，等待人工客服接续处理。','HUMAN_REQUEST',3,NULL,NULL,NULL,300,3600,'2026-10-09 23:11:57','2026-10-10 00:06:57',0,0,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,0,'2026-10-09 23:06:56.516','2026-10-09 23:06:56.516'),(6010,'TKT-20261010152212-5009B6CF',1001,'9e536b74-2d2f-4acd-b6af-40137726cc94',NULL,'AI_PROACTIVE','客户明确要求转人工客服','客户明确要求转人工客服',NULL,NULL,NULL,NULL,'客户在会话中未提供具体问题描述，直接要求转接人工客服。当前无更多上下文信息，已按客户要求提交人工升级。','HUMAN_REQUEST',2,NULL,NULL,NULL,300,3600,'2026-10-10 15:27:13','2026-10-10 16:22:13',0,0,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,0,'2026-10-10 15:22:12.981','2026-10-10 15:22:12.981'),(6011,'TKT-20261012101211-D74A28A9',1001,'517309db-bf07-441f-8e20-87de97e30ef9',NULL,'AI_PROACTIVE','客户明确要求转人工','客户明确要求转人工',NULL,NULL,NULL,NULL,'客户主动提出要转人工客服，未说明具体问题。当前无正在处理的业务请求，按客户要求升级至人工。','HUMAN_REQUEST',3,NULL,NULL,NULL,300,3600,'2026-10-12 10:17:11','2026-10-12 11:12:11',0,0,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,0,'2026-10-12 10:12:11.309','2026-10-12 10:12:11.309'),(6012,'TKT-20261012201329-86437B69',1001,'721a5d92-6639-49a8-876a-7deeec654c59',NULL,'AI_PROACTIVE','客户明确要求转人工客服','客户明确要求转人工客服',NULL,NULL,NULL,NULL,'客户先后咨询退货期限（7天无理由，以签收次日起算）及商品质量问题售后规则。客户现明确要求转人工客服继续处理。目前尚未提供具体订单号，也未创建任何售后申请。','HUMAN_REQUEST',3,NULL,NULL,NULL,300,3600,'2026-10-12 20:18:30','2026-10-12 21:13:30',0,0,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,0,'2026-10-12 20:13:29.522','2026-10-12 20:13:29.522');
