DROP TABLE IF EXISTS `order_info`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `order_info` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT '订单本地ID',
  `tenant_id` bigint(20) unsigned NOT NULL COMMENT '租户ID',
  `external_order_id` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '平台订单号',
  `external_order_number` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '订单展示号(如 #1001,客户常用此搜索)',
  `platform` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '平台',
  `customer_id` bigint(20) unsigned DEFAULT NULL COMMENT '本地客户ID',
  `external_customer_id` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '平台客户ID',
  `customer_email` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户邮箱(下单时填写,可能与 customer.email 不同)',
  `customer_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '收件人姓名',
  `customer_phone` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '收件人电话',
  `shipping_address` json DEFAULT NULL COMMENT '收货地址 {country,state,city,street,zip}',
  `shipping_country` varchar(8) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '收货国家(独立字段便于索引)',
  `shipping_state` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '州/省',
  `shipping_zip` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '邮编',
  `billing_address` json DEFAULT NULL COMMENT '账单地址',
  `order_status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '订单状态:pending/paid/processing/shipped/delivered/cancelled/refunded/returned',
  `payment_status` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '支付状态:unpaid/paid/partially_paid/refunded/partially_refunded',
  `fulfillment_status` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '履约状态:unfulfilled/partial/fulfilled',
  `currency` varchar(8) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'USD' COMMENT '订单币种',
  `subtotal_amount` decimal(15,4) DEFAULT NULL COMMENT '商品小计',
  `shipping_amount` decimal(15,4) DEFAULT NULL COMMENT '运费',
  `tax_amount` decimal(15,4) DEFAULT NULL COMMENT '税费',
  `discount_amount` decimal(15,4) DEFAULT NULL COMMENT '折扣金额',
  `total_amount` decimal(15,4) NOT NULL COMMENT '订单总金额(客户实付)',
  `refunded_amount` decimal(15,4) NOT NULL DEFAULT '0.0000' COMMENT '已退款金额',
  `order_items` json DEFAULT NULL COMMENT '商品列表 [{"sku","title","quantity","price","image_url"}]',
  `item_count` int(11) NOT NULL DEFAULT '0' COMMENT '商品种类数',
  `total_quantity` int(11) NOT NULL DEFAULT '0' COMMENT '商品总件数',
  `tracking_number` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '物流单号(主)',
  `tracking_numbers` json DEFAULT NULL COMMENT '多包裹物流单号列表',
  `tracking_carrier` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '承运商:USPS/UPS/DHL/FedEx/YunExpress',
  `tracking_url` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '物流追踪 URL',
  `tracking_status` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '物流状态:in_transit/out_for_delivery/delivered/exception',
  `tracking_history` json DEFAULT NULL COMMENT '物流轨迹 [{time,location,status,desc}]',
  `tracking_updated_at` datetime DEFAULT NULL COMMENT '物流最后更新时间',
  `estimated_delivery_at` datetime DEFAULT NULL COMMENT '预计送达时间',
  `actual_delivery_at` datetime DEFAULT NULL COMMENT '实际送达时间',
  `tags` json DEFAULT NULL COMMENT '订单标签 ["vip","wholesale"]',
  `discount_codes` json DEFAULT NULL COMMENT '使用的优惠码',
  `note` varchar(1024) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户下单备注',
  `placed_at` datetime NOT NULL COMMENT '下单时间(平台数据)',
  `paid_at` datetime DEFAULT NULL COMMENT '支付时间',
  `shipped_at` datetime DEFAULT NULL COMMENT '发货时间',
  `cancelled_at` datetime DEFAULT NULL COMMENT '取消时间',
  `synced_at` datetime DEFAULT NULL COMMENT '从平台最后同步时间',
  `sync_source` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '同步来源:WEBHOOK/POLL/MANUAL',
  `sync_version` int(11) NOT NULL DEFAULT '0' COMMENT '同步次数(每次+1)',
  `ext_attr` json DEFAULT NULL COMMENT '扩展(平台原始数据快照)',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  `version` int(11) NOT NULL DEFAULT '0' COMMENT '乐观锁',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_tenant_order` (`tenant_id`,`external_order_id`) COMMENT '租户内订单号唯一',
  KEY `idx_tenant_order_number` (`tenant_id`,`external_order_number`) COMMENT '客户常用订单展示号搜索',
  KEY `idx_tenant_email` (`tenant_id`,`customer_email`,`placed_at`) COMMENT '按邮箱查订单',
  KEY `idx_tenant_customer` (`tenant_id`,`customer_id`,`placed_at`) COMMENT '客户的订单列表',
  KEY `idx_tenant_status` (`tenant_id`,`order_status`,`placed_at`) COMMENT '按状态筛选',
  KEY `idx_tenant_placed` (`tenant_id`,`placed_at`) COMMENT '时间倒序',
  KEY `idx_tracking_number` (`tracking_number`) COMMENT '物流单号反查订单',
  KEY `idx_synced_at` (`synced_at`) COMMENT '同步任务调度',
  KEY `idx_phone` (`tenant_id`,`customer_phone`) COMMENT '电话查询'
) ENGINE=InnoDB AUTO_INCREMENT=4111 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='订单信息缓存表';
/*!40101 SET character_set_client = @saved_cs_client */;

