--
-- Table structure for table `product`
--

DROP TABLE IF EXISTS `product`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `product` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT '商品ID',
  `tenant_id` bigint(20) unsigned NOT NULL COMMENT '租户ID',
  `external_product_id` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '平台商品ID',
  `handle` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '商品 URL slug(如 cotton-tshirt)',
  `title` varchar(512) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '商品标题',
  `subtitle` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '副标题',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT '商品详情(可能含 HTML)',
  `description_plain` text COLLATE utf8mb4_unicode_ci COMMENT '商品详情纯文本(去 HTML,用于 embedding)',
  `vendor` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '供应商/品牌',
  `brand` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '品牌',
  `product_type` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '商品类型',
  `category_l1` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '一级类目',
  `category_l2` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '二级类目',
  `category_l3` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '三级类目',
  `categories` json DEFAULT NULL COMMENT '完整分类路径数组',
  `tags` json DEFAULT NULL COMMENT '标签数组',
  `default_sku` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '默认 SKU(简化场景使用)',
  `barcode` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '条形码/UPC/EAN',
  `variants` json DEFAULT NULL COMMENT '变体列表 [{"sku","options":{"color":"red","size":"M"},"price","stock","barcode"}]',
  `variant_count` int(11) NOT NULL DEFAULT '1' COMMENT '变体数量',
  `options_schema` json DEFAULT NULL COMMENT '选项定义 [{"name":"Color","values":["red","blue"]}]',
  `currency` varchar(8) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'USD' COMMENT '币种',
  `price` decimal(12,4) DEFAULT NULL COMMENT '默认价格',
  `compare_at_price` decimal(12,4) DEFAULT NULL COMMENT '划线价(原价)',
  `cost_per_item` decimal(12,4) DEFAULT NULL COMMENT '成本价(店主可见)',
  `total_stock` int(11) NOT NULL DEFAULT '0' COMMENT '总库存',
  `stock_status` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'in_stock/low_stock/out_of_stock/preorder',
  `weight_grams` int(11) DEFAULT NULL COMMENT '重量(克)',
  `dimensions` json DEFAULT NULL COMMENT '尺寸 {length,width,height,unit}',
  `requires_shipping` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否需要发货:0数字商品 1实物',
  `is_taxable` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否计税',
  `featured_image_url` varchar(1024) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '主图 URL',
  `images` json DEFAULT NULL COMMENT '所有图片 URL 数组',
  `videos` json DEFAULT NULL COMMENT '视频 URL 数组',
  `language` varchar(8) COLLATE utf8mb4_unicode_ci DEFAULT 'en' COMMENT '商品默认语言',
  `translations` json DEFAULT NULL COMMENT '多语言翻译 {"es":{"title","description"},"ja":{...}}',
  `seo_title` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `seo_description` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `keywords` json DEFAULT NULL COMMENT 'SEO 关键词',
  `rating_avg` decimal(3,2) DEFAULT NULL COMMENT '平均评分[1,5]',
  `rating_count` int(11) NOT NULL DEFAULT '0' COMMENT '评价总数',
  `review_summary` text COLLATE utf8mb4_unicode_ci COMMENT '评价摘要(用于 RAG)',
  `vector_synced` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否已索引到 PGVector',
  `vector_chunk_count` int(11) NOT NULL DEFAULT '0' COMMENT '索引的 chunk 数',
  `vector_synced_at` datetime DEFAULT NULL COMMENT '最后向量化时间',
  `content_hash` char(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '内容MD5(变化才重新 embedding)',
  `status` tinyint(4) NOT NULL DEFAULT '1' COMMENT '0草稿 1已发布 2已归档 3已售罄下架',
  `published_at` datetime DEFAULT NULL COMMENT '上架时间',
  `synced_at` datetime DEFAULT NULL COMMENT '从平台同步时间',
  `ext_attr` json DEFAULT NULL COMMENT '扩展(原始平台数据)',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0',
  `version` int(11) NOT NULL DEFAULT '0',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_tenant_product` (`tenant_id`,`external_product_id`) COMMENT '租户内商品ID唯一',
  KEY `idx_tenant_handle` (`tenant_id`,`handle`) COMMENT 'URL slug 查询',
  KEY `idx_tenant_sku` (`tenant_id`,`default_sku`) COMMENT 'SKU 查询',
  KEY `idx_tenant_category` (`tenant_id`,`category_l1`,`category_l2`) COMMENT '类目筛选',
  KEY `idx_tenant_status` (`tenant_id`,`status`,`published_at`) COMMENT '上架状态',
  KEY `idx_vector_sync` (`tenant_id`,`vector_synced`,`updated_at`) COMMENT '待索引商品扫描',
  KEY `idx_brand` (`tenant_id`,`brand`) COMMENT '品牌筛选',
  FULLTEXT KEY `ft_title_desc` (`title`,`description_plain`) COMMENT '全文检索退化方案'
) ENGINE=InnoDB AUTO_INCREMENT=3109 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='商品表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `product`
--

LOCK TABLES `product` WRITE;
/*!40000 ALTER TABLE `product` DISABLE KEYS */;
