DROP TABLE IF EXISTS `return_request`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `return_request` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `request_no` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tenant_id` bigint(20) unsigned NOT NULL,
  `request_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'RETURN/REFUND/REPLACEMENT/ADDRESS_CHANGE',
  `external_order_number` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `customer_email` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `reason` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `requested_items` json DEFAULT NULL,
  `amount` decimal(15,4) DEFAULT NULL,
  `currency` varchar(8) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `priority` tinyint(4) NOT NULL DEFAULT '2',
  `status` tinyint(4) NOT NULL DEFAULT '1' COMMENT '1 pending 2 reviewing 3 approved 4 rejected 5 done',
  `approval_required_reason` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `resolution` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `resolution_note` text COLLATE utf8mb4_unicode_ci,
  `ext_attr` json DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_request_no` (`request_no`),
  KEY `idx_tenant_status` (`tenant_id`,`status`,`created_at`),
  KEY `idx_tenant_order` (`tenant_id`,`external_order_number`)
) ENGINE=InnoDB AUTO_INCREMENT=7109 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AI-created customer action requests';
