/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `security_audit_event` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) unsigned DEFAULT NULL,
  `tenant_id` bigint(20) unsigned DEFAULT NULL,
  `action` varchar(96) COLLATE utf8mb4_unicode_ci NOT NULL,
  `outcome` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `subject_hash` char(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `detail` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  KEY `idx_security_audit_user` (`user_id`,`created_at`),
  KEY `idx_security_audit_tenant` (`tenant_id`,`created_at`),
  KEY `idx_security_audit_action` (`action`,`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=84 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='全局认证与权限审计';
/*!40101 SET character_set_client = @saved_cs_client */;

