--
-- Table structure for table `tenant`
--

DROP TABLE IF EXISTS `tenant`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `tenant` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT '租户ID(主键)',
  `tenant_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '租户业务编码(对外展示,如 OM-A1B2C3),全局唯一',
  `store_name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '店铺名称(用户可见)',
  `store_logo_url` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '店铺 Logo URL',
  `store_description` varchar(1024) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '店铺简介',
  `industry` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '行业类目',
  `country_code` varchar(8) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '店铺归属国家 ISO-3166',
  `timezone` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT 'UTC' COMMENT '店铺时区',
  `currency` varchar(8) COLLATE utf8mb4_unicode_ci DEFAULT 'USD' COMMENT '默认结算币种 ISO-4217',
  `platform` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '平台:shopify/amazon/woocommerce/tiktok_shop/... /custom',
  `external_store_id` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '平台店铺ID',
  `external_store_url` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '店铺前台 URL',
  `webhook_secret` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Webhook HMAC 签名密钥(加密存储)',
  `api_credentials_encrypted` text COLLATE utf8mb4_unicode_ci COMMENT '平台 API 凭证(AES-256 加密)',
  `api_credentials_updated_at` datetime DEFAULT NULL COMMENT '凭证最后更新时间',
  `owner_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '店主姓名',
  `owner_email` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '店主邮箱',
  `owner_phone` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '店主手机',
  `owner_country` varchar(8) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '店主国籍',
  `default_lang` varchar(8) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'en' COMMENT '客服默认语言',
  `support_langs` json DEFAULT NULL COMMENT '支持的语言列表',
  `auto_reply_enabled` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否启用 AI 自动回复',
  `business_hours` json DEFAULT NULL COMMENT '工作时段配置',
  `escalation_threshold` decimal(3,2) NOT NULL DEFAULT '0.75' COMMENT '人工升级置信度阈值',
  `escalation_amount_limit` decimal(15,4) DEFAULT '100.0000' COMMENT '金额超此值自动升级',
  `welcome_message` varchar(1024) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '欢迎语模板',
  `signature` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'AI 回复签名',
  `subscription_plan` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'FREE' COMMENT '订阅计划',
  `subscription_started_at` datetime DEFAULT NULL COMMENT '订阅生效时间',
  `subscription_expires_at` datetime DEFAULT NULL COMMENT '订阅到期时间',
  `monthly_token_budget` bigint(20) NOT NULL DEFAULT '100000' COMMENT '月度Token预算上限',
  `monthly_message_quota` int(11) NOT NULL DEFAULT '1000' COMMENT '月度消息条数上限',
  `qps_limit` int(11) NOT NULL DEFAULT '5' COMMENT 'API 请求 QPS 上限',
  `concurrent_session_limit` int(11) NOT NULL DEFAULT '50' COMMENT '同时在线会话数上限',
  `status` tinyint(4) NOT NULL DEFAULT '1' COMMENT '0:停用 1:启用 2:试用中 3:欠费暂停 4:封禁',
  `status_reason` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '当前状态原因',
  `last_active_at` datetime DEFAULT NULL COMMENT '最后活跃时间',
  `ext_attr` json DEFAULT NULL COMMENT '扩展属性',
  `remark` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '内部备注',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除:0否1是',
  `version` int(11) NOT NULL DEFAULT '0' COMMENT '乐观锁版本号',
  `created_by` bigint(20) DEFAULT NULL COMMENT '创建人ID',
  `updated_by` bigint(20) DEFAULT NULL COMMENT '更新人ID',
