--
-- Table structure for table `tool_call_log`
--

DROP TABLE IF EXISTS `tool_call_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `tool_call_log` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT '日志ID',
  `trace_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '链路追踪ID',
  `span_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Span ID(若集成 OpenTelemetry)',
  `tenant_id` bigint(20) unsigned NOT NULL COMMENT '租户ID',
  `conversation_uuid` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '会话UUID',
  `message_uuid` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关联的 assistant 消息UUID',
  `tool_call_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '工具调用ID(本地位)',
  `tool_name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '工具名',
  `tool_version` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT 'v1' COMMENT '工具版本(支持灰度)',
  `params` json DEFAULT NULL COMMENT '入参 JSON',
  `params_hash` char(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '入参MD5(用于缓存命中判断)',
  `success` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否成功',
  `result` json DEFAULT NULL COMMENT '返回结果',
  `result_size_bytes` int(11) DEFAULT NULL COMMENT '返回数据大小(便于发现异常大返回)',
  `error_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '错误码',
  `error_message` varchar(2048) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '错误信息',
  `error_stack` text COLLATE utf8mb4_unicode_ci COMMENT '异常堆栈(仅 ERROR 级别才存)',
  `started_at` datetime(3) NOT NULL COMMENT '开始时间',
  `ended_at` datetime(3) DEFAULT NULL COMMENT '结束时间',
  `latency_ms` int(11) DEFAULT NULL COMMENT '耗时 ms',
  `cache_hit` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否命中缓存',
  `retry_count` int(11) NOT NULL DEFAULT '0' COMMENT '重试次数',
  `is_retry` tinyint(1) NOT NULL DEFAULT '0' COMMENT '本次是否是重试',
  `original_call_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '首次调用ID(若是重试)',
  `iteration_index` tinyint(4) DEFAULT NULL COMMENT 'ReAct 第几轮',
  `triggered_by_model` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '触发本次调用的 LLM 模型',
  `client_ip` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户端 IP',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  KEY `idx_trace` (`trace_id`) COMMENT '链路追踪',
  KEY `idx_tenant_tool` (`tenant_id`,`tool_name`,`created_at`) COMMENT '工具调用统计',
  KEY `idx_tenant_success` (`tenant_id`,`success`,`created_at`) COMMENT '失败率统计',
  KEY `idx_conversation` (`conversation_uuid`,`created_at`) COMMENT '会话工具链',
  KEY `idx_message` (`message_uuid`) COMMENT '消息关联工具',
  KEY `idx_created` (`created_at`) COMMENT '时间范围扫描'
) ENGINE=InnoDB AUTO_INCREMENT=44 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='工具调用日志';
/*!40101 SET character_set_client = @saved_cs_client */;

